use IO::Handle;
use overload ();
use File::Spec ();
require "$file.pm"
use parent qw(IO::Handle);
sub is_real_fh ($) {
    my $fh = shift;

    {
        no warnings 'uninitialized';
        return FALSE if -p $fh or -c _ or -b _;
